<?php require __DIR__.'/../../bootstrap/app.php';role_required('admin');$db=Database::get();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';
 if($a==='add'){$n=trim((string)($_POST['name']??''));if(mb_strlen($n)<2||mb_strlen($n)>120)notice('Name must be 2-120 characters.');else try{$db->prepare("INSERT INTO product_categories(name) VALUES(?)")->execute([$n]);audit('add category','category');notice('Category added.');}catch(PDOException $x){notice('That category already exists.');}}
 if($a==='delete'){$id=(int)($_POST['id']??0);$db->prepare("DELETE FROM product_categories WHERE id=?")->execute([$id]);audit('delete category','category',$id);notice('Category deleted. Its products are now uncategorized.');}
 go('admin/categories.php');}
$rows=$db->query("SELECT c.id,c.name,COUNT(p.id) n FROM product_categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name")->fetchAll();
$title='Categories';require __DIR__.'/../../app/Views/header.php';?><section class="section"><div class="container"><div class="dash"><?php require __DIR__.'/../../app/Views/admin_nav.php';?><div><h1>Product categories</h1><form method="post" class="cardx mb-4 d-flex gap-2"><?=csrf_field()?><input type="hidden" name="action" value="add"><input class="form-control" name="name" placeholder="New category" required maxlength="120"><button class="btn btn-dark">Add</button></form>
<table class="table"><tr><th>Name</th><th>Products</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=(int)$r['n']?></td><td><form method="post" onsubmit="return confirm('Delete this category?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-link text-danger p-0">Delete</button></form></td></tr><?php endforeach;?></table></div></div></div></section><?php require __DIR__.'/../../app/Views/footer.php';?>
